"""The case files: fictional investigations solved in the simulated terminal (Cases.py serves them).

Everything here is invented: people, companies, websites (all on the reserved .example domain), records.
How a case plays: the agent searches a source (web, social, records, whois, archive, image) with a query.
A document turns up when one of its `keys` matches the query (every word of the key is in the query, or the
key written without spaces/punctuation is). Rare keys (usernames, file names, tracking IDs) are the pivots:
you only find those documents once an earlier document told you what to type.
Questions are answered in free text and checked against `accept` (lower-cased, letters and digits only,
the answer must contain one of them). Two hints per question; hints and wrong answers lower the score.
"""

SOURCES = {
    "web": {"label": "Web search", "icon": "search", "hint": "Keywords, names in quotes, phrases"},
    "social": {"label": "Social", "icon": "users", "hint": "A name or a @username"},
    "records": {"label": "Public records", "icon": "book", "hint": "A person, company or address"},
    "whois": {"label": "WHOIS", "icon": "globe", "hint": "A domain, e.g. shop.example"},
    "archive": {"label": "TimeVault archive", "icon": "clock", "hint": "A website, page or @handle"},
    "image": {"label": "Image lab", "icon": "camera", "hint": "A photo file name, e.g. IMG_0001.jpg"},
}

